exercises.solution:
import json

def parse_reply(text):
    try:
        data = json.loads(text)
    except json.JSONDecodeError:
        return None
    return data if isinstance(data, dict) else None

def strip_fence(text):
    text = text.strip()
    if text.startswith("```"):
        lines = text.split("\n")[1:]
        if lines and lines[-1].strip() == "```":
            lines = lines[:-1]
        text = "\n".join(lines)
    return text.strip()

def get_label(text, allowed):
    data = parse_reply(strip_fence(text))
    if data is None:
        return "unknown"
    label = data.get("label")
    if label in allowed:
        return label
    return "unknown"
